    public static string Get(string language, string key)
    {
        var i = language switch { "ru" => 1, "uk" => 2, "en" => 3, "es" => 4, _ => 0 };
        if (Map.TryGetValue(key, out var row) && i < row.Length && !string.IsNullOrEmpty(row[i]))
            return row[i];
        if (Map.TryGetValue(key, out var de) && de.Length > 0)
            return de[0];
        return key;
    }

    public static IEnumerable<string> Keys => Map.Keys;

    internal static void EnsureComplete()
    {
        foreach (var kv in Map)
        {
            if (kv.Value.Length != 5)
                throw new InvalidOperationException("Loc key " + kv.Key + " needs de/ru/uk/en/es.");
            for (var i = 0; i < 5; i++)
                if (string.IsNullOrEmpty(kv.Value[i]))
                    throw new InvalidOperationException("Loc key " + kv.Key + " is empty at index " + i);
        }
    }
